63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
71	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
72	     * stored lower-cased.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * The maximum number of owners a single city may contain. Once a city already holds this many
79	     * owners, any further create naming that city is rejected as a conflict.
80	     */
81	    private static final int MAX_OWNERS_PER_CITY = 50;
82	
83	    /**
84	     * The maximum number of owners that may be registered in a single day. Once this many owners
85	     * already carry today's registration date, any further create is rejected as too many requests.
86	     */
87	    private static final int MAX_OWNERS_PER_DAY = 100;
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        validateRequiredOwnerFields(ownerFieldsDto);
136	        rejectDailyLimitExceeded();
137	        rejectCityAtCapacity(ownerFieldsDto.getCity());
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        owner.setAddress(normalizeAddress(owner.getAddress()));
141	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
142	        owner.setTelephone(normalizedTelephone);
143	        rejectDuplicateTelephone(normalizedTelephone);
144	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
145	        owner.setEmail(normalizeEmail(owner.getEmail()));
146	        if (owner.getRegistrationDate() == null) {
147	            owner.setRegistrationDate(LocalDate.now());
148	        }
149	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
150	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
151	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
171	        this.clinicService.saveOwner(currentOwner);
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Transactional
177	    @Override
178	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        this.clinicService.deleteOwner(owner);
184	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        HttpHeaders headers = new HttpHeaders();
195	        Pet pet = petMapper.toPet(petFieldsDto);
196	        owner.setId(ownerId);
197	        pet.setOwner(owner);
198	        pet.getType().setName(null);
199	        this.clinicService.savePet(pet);
200	        PetDto petDto = petMapper.toPetDto(pet);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
