236	    }
237	
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner != null) {
244	            Pet pet = owner.getPet(petId);
245	            if (pet != null) {
246	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
247	            }
248	        }
249	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	    }
251	
252	    /**
253	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
254	     * offending field is collected so the caller learns exactly which values must be supplied.
255	     *
256	     * @param ownerFieldsDto the submitted owner payload
257	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
258	     *         telephone is missing or blank
259	     */
260	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
261	        List<String> missingFields = new ArrayList<>();
262	        if (isBlank(ownerFieldsDto.getFirstName())) {
263	            missingFields.add("firstName");
264	        }
265	        if (isBlank(ownerFieldsDto.getLastName())) {
266	            missingFields.add("lastName");
267	        }
268	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
269	            missingFields.add("address");
270	        }
271	        if (isBlank(ownerFieldsDto.getCity())) {
272	            missingFields.add("city");
273	        }
274	        if (isBlank(ownerFieldsDto.getTelephone())) {
275	            missingFields.add("telephone");
276	        }
277	        if (!missingFields.isEmpty()) {
278	            throw new MissingOwnerFieldsException(missingFields);
279	        }
280	    }
281	
282	    private boolean isBlank(String value) {
283	        return value == null || value.isBlank();
284	    }
285	
286	    /**
287	     * Counts the existing owners who, before this create, already share the given first and last name.
288	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
289	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
290	     * case or spacing still count as the same name.
291	     *
292	     * @param firstName the first name of the owner being created
293	     * @param lastName the last name of the owner being created
294	     * @return the number of existing owners sharing both names (zero when none)
295	     */
296	    private int countNamesakes(String firstName, String lastName) {
297	        String first = normalizeHouseholdField(firstName);
298	        String last = normalizeHouseholdField(lastName);
299	        return (int) this.clinicService.findAllOwners().stream()
300	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
301	                && normalizeHouseholdField(existing.getLastName()).equals(last))
302	            .count();
303	    }
304	
305	    /**
306	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
307	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
308	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
309	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
310	     * more owners the create is rejected as a conflict.
311	     *
312	     * @param city the city of the owner being created
313	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
314	     */
315	    /**
316	     * Rejects an owner create once the maximum number of owners have already been registered today.
317	     * Owners are grouped by their {@code registrationDate}; when {@link #MAX_OWNERS_PER_DAY} or more
318	     * existing owners already carry today's date the create is rejected as too many requests. A new
319	     * owner that supplies no registration date is dated today, so this quota bounds the number of
320	     * owners that may be created on any single day.
321	     *
322	     * @throws OwnerDailyLimitExceededException if today already holds the maximum number of owners
323	     */
324	    private void rejectDailyLimitExceeded() {
325	        LocalDate today = LocalDate.now();
326	        long ownersToday = this.clinicService.findAllOwners().stream()
327	            .filter(existing -> today.equals(existing.getRegistrationDate()))
328	            .count();
329	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
330	            throw new OwnerDailyLimitExceededException(today, MAX_OWNERS_PER_DAY);
331	        }
332	    }
333	
334	    private void rejectCityAtCapacity(String city) {
335	        String normalizedCity = normalizeHouseholdField(city);
336	        long ownersInCity = this.clinicService.findAllOwners().stream()
337	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
338	            .count();
339	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
340	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
341	        }
342	    }
343	
344	    /**
345	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
346	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
347	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
348	     * of owners already in that city (e.g. 'SYD-SMI-0007').
349	     *
350	     * @param city the owner's city
351	     * @param lastName the owner's last name
352	     * @return the formatted customer code
353	     */
354	    private String generateCustomerCode(String city, String lastName) {
355	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
356	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
357	        String normalizedCity = normalizeHouseholdField(city);
358	        int sequence = (int) this.clinicService.findAllOwners().stream()
359	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
360	            .count() + 1;
361	        return String.format("%s-%s-%04d", city3, last3, sequence);
362	    }
363	
364	    /**
365	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
366	     * customerCode is the owner's customer code and YY is the last two digits of the
367	     * registrationDate year (e.g. 'SMI-0007-M26').
368	     *
369	     * @param customerCode the owner's customer code
370	     * @param registrationDate the owner's registration date
371	     * @return the formatted membership number
372	     */
373	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
374	        String yy = String.format("%02d", registrationDate.getYear() % 100);
375	        return customerCode + "-M" + yy;
376	    }
377	
378	    /**
379	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
380	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
381	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
382	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
383	     * stored and returned.
384	     *
385	     * @param telephone the raw telephone value from the request
386	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
387	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
388	     */
389	    private String normalizeTelephone(String telephone) {
390	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
391	        String e164;
392	        if (cleaned.startsWith("+")) {
393	            e164 = cleaned;
394	        } else {
395	            String national = cleaned;
396	            if (national.startsWith("0")) {
397	                national = national.substring(1);
398	            }
399	            e164 = "+61" + national;
400	        }
401	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
402	            throw new InvalidOwnerFieldsException(List.of("telephone"));
403	        }
404	        return e164;
405	    }
406	
407	    /**
408	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
409	     * left unset. When a value is present it must be a syntactically valid address; the normalized
410	     * form stored and returned is the value lower-cased.
411	     *
412	     * @param email the raw email value from the request, or {@code null} when none was supplied
413	     * @return the lower-cased email, or {@code null} when no email was supplied
414	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
415	     */
416	    private String normalizeEmail(String email) {
417	        if (email == null || email.isBlank()) {
418	            return null;
419	        }
420	        if (!EMAIL_PATTERN.matcher(email).matches()) {
421	            throw new InvalidOwnerFieldsException(List.of("email"));
422	        }
423	        return email.toLowerCase(Locale.ROOT);
424	    }
425	
426	    /**
427	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
428	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
429	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
430	     * normalized form is what gets stored, returned and used for every address comparison (the
431	     * required-field check, household duplicate detection and the shared household id).
432	     *
433	     * @param address the raw address value from the request, or {@code null}
434	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
435	     */
436	    private String normalizeAddress(String address) {
437	        if (address == null) {
438	            return "";
439	        }
440	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
441	        if (collapsed.isEmpty()) {
442	            return "";
443	        }
444	        String[] tokens = collapsed.split(" ");
445	        for (int i = 0; i < tokens.length; i++) {
446	            switch (tokens[i]) {
447	                case "ST" -> tokens[i] = "STREET";
448	                case "RD" -> tokens[i] = "ROAD";
449	                case "AVE" -> tokens[i] = "AVENUE";
450	                default -> { }
451	            }
452	        }
453	        return String.join(" ", tokens);
454	    }
455	
456	    /**
457	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
458	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
459	     * directly and is therefore independent of the punctuation a caller supplied.
460	     *
461	     * @param e164Telephone the E.164 telephone of the owner being created
462	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
463	     */
464	    private void rejectDuplicateTelephone(String e164Telephone) {
465	        boolean inUse = this.clinicService.findAllOwners().stream()
466	            .map(Owner::getTelephone)
467	            .filter(existing -> existing != null)
468	            .anyMatch(e164Telephone::equals);
469	        if (inUse) {
470	            throw new DuplicateOwnerTelephoneException(e164Telephone);
471	        }
472	    }
473	
474	    /**
475	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
476	     * last name and a normalized address: last names are compared case-insensitively after whitespace
477	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
478	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
479	     * abbreviation still count as the same household.
480	     * <p>
481	     * When the owner's last name and address already belong to at least one other owner the behaviour
482	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
483	     * household. If it is true the create is allowed and every member of the household - the existing
484	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
485	     * read. When no other owner shares the last name and address no identifier is assigned.
486	     *
487	     * @param owner the owner being created
488	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
489	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
490	     *         address and {@code sharesHousehold} is not true
491	     */
492	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
493	        String lastName = normalizeHouseholdField(owner.getLastName());
494	        String address = normalizeAddress(owner.getAddress());
495	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
496	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
497	                && normalizeAddress(existing.getAddress()).equals(address))
498	            .toList();
499	        if (housemates.isEmpty()) {
500	            return;
501	        }
502	        if (!Boolean.TRUE.equals(sharesHousehold)) {
503	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
504	        }
505	        String householdId = generateHouseholdId(lastName, address);
506	        owner.setHouseholdId(householdId);
507	        for (Owner housemate : housemates) {
508	            if (!householdId.equals(housemate.getHouseholdId())) {
509	                housemate.setHouseholdId(householdId);
510	                this.clinicService.saveOwner(housemate);
511	            }
512	        }
513	    }
514	
515	    /**
516	     * Builds the stable identifier shared by the members of one household. It is derived purely from
517	     * the normalized last name and address, so every owner of a given household deterministically
518	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
519	     * two normalized fields joined by a single space.
520	     *
521	     * @param normalizedLastName the household's last name, already normalized for comparison
522	     * @param normalizedAddress the household's address, already normalized for comparison
523	     * @return the shared household identifier
524	     */
525	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
526	        String key = normalizedLastName + '�' + normalizedAddress;
527	        try {
528	            byte[] digest = MessageDigest.getInstance("SHA-256")
529	                .digest(key.getBytes(StandardCharsets.UTF_8));
530	            StringBuilder hex = new StringBuilder();
531	            for (byte b : digest) {
532	                hex.append(String.format("%02X", b));
533	                if (hex.length() >= 12) {
534	                    break;
535	                }
536	            }
537	            return hex.substring(0, 12);
538	        } catch (NoSuchAlgorithmException e) {
539	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
540	        }
541	    }
542	
543	    /**
544	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
545	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
546	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
547	     * expands common abbreviations.
548	     *
549	     * @param value the raw last name, or {@code null}
550	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
551	     */
552	    private String normalizeHouseholdField(String value) {
553	        if (value == null) {
554	            return "";
555	        }
556	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
557	    }
558	}
